import type { KnipConfig } from "knip";

/**
 * Unused files, exports and dependencies (11 §6, `pnpm lint:unused`). Placeholders that exist only
 * for a later milestone are ignored here with that milestone named, and removed from this list
 * when it lands. Gitignored paths (the CI caches) need no entry; `lint:unused` fails on any entry
 * that has become redundant (a configuration hint).
 */
const config: KnipConfig = {
  ignore: [
    // M3: the game shell lazy-loads game clients through the generated import map.
    "apps/web/src/games.ts",
    // Generated by openapi-typescript (`pnpm api:generate`); its exports are its whole surface.
    "packages/api-client/src/schema.ts",
  ],
  // osv-scanner is installed by mise (11 §1), not npm; db:check runs drizzle-kit in
  // packages/server, which depends on it.
  ignoreBinaries: ["osv-scanner", "drizzle-kit"],
  workspaces: {
    ".": {
      entry: ["instance.config.ts"],
      project: ["*.{ts,js,mjs}"],
      // Installed game packages: named in instance.config.ts and imported only by the generated,
      // git-ignored registry and client import map (02 §7.3), which knip doesn't read.
      ignoreDependencies: ["@your-move/game-example", "@your-move/game-words"],
    },
    "apps/node": {
      project: ["src/**/*.ts", "scripts/**/*.ts"],
      // Build-order dependency: the build copies the web app's output (pnpm builds it first).
      ignoreDependencies: ["@your-move/web"],
    },
    "apps/worker": {
      project: ["src/**/*.ts", "scripts/**/*.ts"],
      // Build-order dependency: the build copies the web app's output (pnpm builds it first).
      ignoreDependencies: ["@your-move/web"],
    },
    "apps/web": {
      project: ["src/**/*.{ts,tsx}", "sw/**/*.ts"],
      // Imported by the build (vite.config.ts, via build/service-worker.ts) for the server paths.
      ignoreDependencies: ["@your-move/shared"],
    },
    scripts: { entry: ["src/bin/*.ts"], project: ["src/**/*.ts"] },
    "tests/contract": { entry: ["src/**/*.test.ts"], project: ["src/**/*.ts"] },
    "tests/e2e": { entry: ["src/**/*.spec.ts"], project: ["src/**/*.ts"] },
  },
};

export default config;
